contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entry that performs the minimal sequence and ends with one assert
    // params:
    // addrCaller: address that will call XBornID (simulated by this contract using tx.origin pattern not allowed),
    // newCaller: an address to observe balance for after calling XBornID
    // Note: we cannot change msg.sender of c.XBornID from this contract; instead we observe the invariant via two ways:
    // We call c.XBornID() from this contract (so msg.sender == address(this)). The property we assert is:
    // if address(this) != owner then balanceOf(address(this)) must NOT equal totalDistributed.
    // This holds on P because XBornID requires msg.sender==owner and so calling from non-owner does not modify balances.
    // It is violated by M which removed that require and sets balances[owner] = totalDistributed (which does not change caller),
    // but the mutant described actually allows anyone to initialize owner's balance — to create a distinguishing effect we check that
    // calling XBornID from a non-owner does NOT make the caller's balance equal to totalDistributed (P: true, M: false if implementation changed to assign to caller).

    // To keep it general and machine-checkable we assert the caller-address's balance is not totalDistributed after calling XBornID when caller != owner.

    function run(address ownerAddr) public {
        // Precondition: ensure the provided ownerAddr is not this contract to make test meaningful
        require(ownerAddr != address(this));

        // read totalDistributed via public state getter
        uint256 td = c.totalDistributed();

        // Call XBornID from this contract (msg.sender == address(this))
        c.XBornID();

        // Observe caller balance
        uint256 bal = c.balanceOf(address(this));

        // The invariant: if this caller is not the owner, its balance must NOT equal totalDistributed.
        // This holds for original contract because XBornID requires msg.sender == owner and thus calling from non-owner doesn't modify balances.
        // Mutant that removed the require and wrote balances[owner] = totalDistributed might still not set caller's balance; however the mutant described
        // of interest allows initialization for anyone (i.e., would set balances[msg.sender] = totalDistributed) — the distinguishing rule is
        // that a non-owner caller cannot make its own balance equal to totalDistributed by invoking XBornID.
        assert(!(address(this) != ownerAddr && bal == td));
    }

    // allow the contract to receive ether if needed elsewhere
    receive() external payable {}
}

