pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed actor: any address (could be owner or not). We check that only the real owner can cause balances to be set
    function testFuzz_property(address actor) public {
        // keep actor wide but avoid zero address which might be special in some contexts
        vm.assume(actor != address(0));

        // Query owner (owner is the deployer, i.e., address(this) when c was constructed in setUp)
        address owner = address(this);

        // Read balance of a chosen key (we use actor) before calling
        uint256 before = c.balanceOf(actor);

        // We will attempt to call XBornID() as actor
        bool ok;
        // make the call as the fuzzed actor
        vm.prank(actor);
        try c.XBornID() {
            ok = true;
        } catch {
            ok = false;
        }

        // Read balance after the call
        uint256 after = c.balanceOf(actor);

        // General rule (one assertion): If caller is not the owner, then the reference contract guarantees that balances[actor] remains unchanged after calling XBornID(); the mutant (which removes the owner check) allows non-owners to change balances, so for some actor the value will differ.
        // We express the invariant as: if actor != owner then balances[actor] == before after calling XBornID().
        // This holds for the correct contract for all actor values; the mutant will fail for some actor (non-owner) because it allows mutation.
        if (actor != owner) {
            assertTrue(after == before);
        } else {
            // if actor is the owner, original contract sets owner's balance to totalDistributed; we don't assert on that here
            assertTrue(true);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: perform approve then transferFrom and assert allowance decreased
    function runTest(address from, address spender, address to, uint256 approveAmount, uint256 transferAmount) public {
        // Preconditions to avoid trivial reverts and ensure meaningful check
        require(from != address(0) && spender != address(0) && to != address(0));
        require(spender != from); // spender should be distinct
        require(approveAmount >= transferAmount);
        require(transferAmount > 0);

        // We need 'from' to have enough balance. The contract C initially gives owner balances in constructor
        // We cannot transfer tokens from arbitrary 'from' unless 'from' has tokens. So we arrange flow where 'from' is msg.sender of this test caller.
        // To keep general and minimal, require that this contract has enough tokens and use transfer to 'from' if needed.

        // Get initial allowance (should be zero or some value)
        uint256 beforeAllow = c.allowance(from, spender);

        // Approve: must be called by 'from'. So we require that 'from' is address(this) or we cannot call approve as 'from'.
        // To satisfy that without extra complexity, require caller supplies 'from' == address(this).
        require(from == address(this));

        // Ensure this contract has enough balance to approve and transferFrom: get current balance of this contract
        uint256 selfBal = c.balanceOf(address(this));
        // If not enough, we cannot mint; but initial contract C sets balances for owner only. To make test general, rely on caller to pick parameters where balance is sufficient.
        require(selfBal >= approveAmount && selfBal >= transferAmount);

        // Approve spender
        bool ok = c.approve(spender, approveAmount);
        require(ok);

        // Record allowance after approve
        uint256 afterApproveAllow = c.allowance(from, spender);
        require(afterApproveAllow >= transferAmount);

        // Now have the spender (spender address) call transferFrom. We cannot make c calls originate from arbitrary 'spender' here
        // But we can simulate by having this contract call transferFrom on behalf of spender only if this contract is the msg.sender matching spender.
        // So require spender == address(this) so that our call to transferFrom is made as the approved spender.
        require(spender == address(this));

        // Perform transferFrom: from == address(this), spender == address(this)
        bool txok = c.transferFrom(from, to, transferAmount);
        require(txok);

        // Check allowance decreased by exactly transferAmount
        uint256 finalAllow = c.allowance(from, spender);

        // The property: finalAllow == afterApproveAllow - transferAmount
        assert(finalAllow == (afterApproveAllow - transferAmount));
    }

    // Allow this contract to receive ETH if needed by c.getTokens in other tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: owner O, spender S (msg.sender), recipient R, initialAllowance, amount
    function run(address owner, address recipient, uint256 initialAllowance, uint256 amount) public payable {
        // preconditions: amount > 0, initialAllowance == amount, owner != address(0), recipient != address(0)
        require(amount > 0 && initialAllowance == amount && owner != address(0) && recipient != address(0));

        // Arrange: owner must approve this contract (as spender) for initialAllowance.
        // We call c.approve from owner by using c.transferOwnership/other means is not possible here,
        // so instead we rely on the public surface: we use allowance and transferFrom directly.
        // To ensure the allowance equals initialAllowance, require that calling transferFrom once by this contract will succeed (i.e., allowed[owner][address(this)] >= amount and balances[owner] >= amount).
        // We cannot set up owner state directly; however the specification requires only observable rule after a successful transferFrom.
        // So first, attempt transferFrom; it must succeed for the assertion to be meaningful. If it reverts, test will revert and not reach assert.

        // Call the first transferFrom: this should consume allowance in original contract.
        c.transferFrom(owner, recipient, amount);

        // Now try a second transferFrom of the same amount. In the original contract this should fail (revert) because allowance was reduced to zero; in the mutant it will succeed.
        bool secondReverted = false;
        // We detect revert by calling via low-level call to the contract's function selector.
        // Build calldata for transferFrom(address,address,uint256)
        bytes memory data = abi.encodeWithSignature("transferFrom(address,address,uint256)", owner, recipient, amount);
        (bool ok, ) = address(c).call(data);
        secondReverted = !ok;

        // Assert that the second transferFrom reverted (i.e., allowance was decreased by the first call)
        assert(secondReverted == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, address spender, uint256 amount, uint256 initialAllowance) public payable {
        // precondition: setup requires non-zero amount, distinct addresses, and that allowed[from][spender] >= amount
        require(from != address(0) && to != address(0) && spender != address(0));
        require(amount > 0);
        // Ensure the precondition that original contract would have allowed the transfer:
        require(initialAllowance >= amount);

        // We cannot write into c.allowed directly. Instead, we rely on the public approve/transferFrom behavior.
        // Set up: have 'from' own enough balance and have given allowance to 'spender'. We cannot simulate different msg.sender easily,
        // but the distinguishing observation only needs to read allowance before and after a transferFrom call executed by this contract as spender.
        // So require that this contract is the spender.
        // Precondition: initialAllowance is the allowance that this contract (as spender) has from 'from'.

        // Read allowance before the state-changing call
        uint256 before = c.allowance(from, address(this));

        // The test assumes the contract already has the allowance >= amount; enforce it by requiring equality to provided initialAllowance
        require(before == initialAllowance);

        // Perform the transferFrom as this contract (the spender). This is the single state-changing call on c in top-level form.
        bool success = c.transferFrom(from, to, amount);

        // Read allowance after the call
        uint256 after = c.allowance(from, address(this));

        // General rule: if transferFrom returned true (succeeded), the allowance must have decreased
        assert(!success || after < before);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address ownerAddr, address spenderAddr, address to, uint256 initialAllowance, uint256 transferAmount) public payable {
        require(ownerAddr != address(0) && spenderAddr != address(0) && to != address(0));
        // set up: owner must have enough balance and allowance must be set to initialAllowance
        // We cannot call internal functions of C, but we can rely on approve being callable by this contract when msg.sender == owner
        // So run as if this contract is owner by expecting ownerAddr == address(this)
        require(ownerAddr == address(this));
        // Ensure contract has sufficient tokens to allow transferFrom by spender: minting/distribution already done in C constructor; assume balance exists
        // Approve spender
        bool ok = c.approve(spenderAddr, initialAllowance);
        require(ok);
        // Now perform transferFrom as spender: need to call c.transferFrom from spenderAddr. We cannot make this contract become spenderAddr.
        // Instead, we simulate by having the spenderAddr call transferFrom via low-level call forwarding the calldata.
        // Build calldata for transferFrom(address,uint256)
        // But Solidity disallows impersonation; however we can invoke transferFrom by using address(spenderAddr).call with encoded selector.
        // Prepare calldata for transferFrom(ownerAddr, to, transferAmount)
        bytes memory data = abi.encodeWithSelector(c.transferFrom.selector, ownerAddr, to, transferAmount);
        // Make the low-level call from this contract but set msg.sender to this contract — to emulate spender we require spenderAddr == address(this)
        require(spenderAddr == address(this));
        (bool success, ) = address(c).call(data);
        require(success);
        // After successful transferFrom, the allowance must have decreased by transferAmount
        uint256 after = c.allowance(ownerAddr, spenderAddr);
        uint256 expected = (initialAllowance >= transferAmount) ? (initialAllowance - transferAmount) : 0;
        // General rule: allowance equals initialAllowance - transferAmount (with underflow protected by require in contract)
        assert(after == expected);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address ownerAddr, address spenderAddr, address toAddr, uint256 amount, uint256 initialAllowance) public payable {
        // precondition: valid nonzero transfer amount and distinct addresses and sufficient balances/allowance
        require(amount > 0);
        require(ownerAddr != address(0) && spenderAddr != address(0) && toAddr != address(0));
        require(ownerAddr != toAddr);
        // set up: we need the contract to have appropriate allowance and balance; we observe only via public calls
        // Ensure the allowance is at least `amount` by assuming caller previously set it off-chain; require here for generality
        require(c.allowance(ownerAddr, spenderAddr) >= amount);
        // Ensure owner has enough balance
        require(c.balanceOf(ownerAddr) >= amount);

        uint256 before = c.allowance(ownerAddr, spenderAddr);
        // perform the state-changing operation that differs between original and mutant
        c.transferFrom(ownerAddr, toAddr, amount);
        uint256 afterAllowance = c.allowance(ownerAddr, spenderAddr);
        // general rule: after a successful transferFrom of a positive amount, the allowance decreases
        assert(afterAllowance < before);
    }
    receive() external payable { }
}
